--
-- Name: api_resource; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.api_resource (
    id character(36) NOT NULL,
    cursor_key integer NOT NULL,
    name character varying(255) NOT NULL,
    identifier character varying(255) NOT NULL,
    tenant_id integer,
    description character varying(255),
    type character varying(255) NOT NULL,
    requires_authorization boolean NOT NULL
);


--
-- Name: api_resource_cursor_key_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.api_resource_cursor_key_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: api_resource_cursor_key_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.api_resource_cursor_key_seq OWNED BY public.api_resource.cursor_key;


--
-- Name: api_resource_property_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.api_resource_property_seq
    START WITH 1
